            if ch == 'X':
                x_count += 1
            elif ch == 'O':
                o_count += 1
    if o_count > x_count or x_count - o_count > 1:
        return False
    x_wins = _wins(board, 'X')
    o_wins = _wins(board, 'O')
    if x_wins and o_wins:
